(()=>{'use strict';
const $=id=>document.getElementById(id);let data=null,fullData=null,active='home',editing=null,reservationMonth=new Date().toISOString().slice(0,7),temp={ingredients:[],baseUses:[]},tpvZone='sala',tpvCategory='',tpvOrderId=null,tpvProductPage=0,tpvFamilyPage=0;
const menu=[
 ['FRONT OFFICE','tpv','▣ Sala / TPV'],['','saleItems','Begudes / articles de venda'],
 ['','home','⌂ Inici'],['CONFIGURACIÓ','company','Empresa, logotip i GPS'],['','documents','Cartes, menús i pressupostos'],['','backup','Còpies de seguretat'],
 ['MAGATZEM','suppliers','Proveïdors'],['','products','Productes / Magatzem'],['','ocr','OCR · Crear productes'],
 ['CUINA','bases','Bases de cuina'],['','dishes','Fitxes de plats'],
 ['CONTROL DE QUALITAT','control','Control Normatiu'],
 ['RESERVES','reservations','Gestió de reserves'],
 ['RRHH','employees','Empleats'],['','schedules','Horaris'],['','punches','Registre GPS de fitxatges'],
 ['DIRECCIÓ','permissions','Matriu de permisos']
];
const titles={tpv:['Sala / TPV','Zona → taula → família → producte → comanda'],saleItems:['Begudes / articles de venda','Formats i preus importats d’Ágora, editables a Casa Mestres'],home:['Inici','Estructura única i sense funcions duplicades'],company:['Configuració','Empresa, logotip, dades i zona GPS'],documents:['Documents comercials','Cartes, menús, pressupostos i propostes de grup'],backup:['Còpies de seguretat','Descarregar o restaurar tota l’app'],suppliers:['Proveïdors','Dades bàsiques dels proveïdors'],products:['Productes / Magatzem','Codi, nom, preu, unitat i família'],ocr:['OCR','Llegir i crear productes directament'],bases:['Bases de cuina','Bases amb ingredients, cost i procés'],dishes:['Fitxes de plats','La fitxa incorpora l’escandall'],control:['Control de Qualitat','Eina completa de Control Normatiu'],employees:['Empleats','Personal actiu'],schedules:['Horaris','Planificació de torns'],punches:['Fitxatges GPS','Entrada, pausa, retorn i sortida'],reservations:['Gestió de reserves','Calendari, clients, menús, fiances i estat de pagament'],permissions:['Matriu de permisos','Direcció · empresa, centre, empleat, nivell i historial']};
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function uid(prefix){return prefix+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7)}
function money(n){return (Number(n)||0).toFixed(2).replace('.',',')+' €'}
function n(v){const x=Number(v);return Number.isFinite(x)?x:0}
function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
const SCOPED_COLLECTIONS=['suppliers','products','bases','dishes','saleItems','documents','employees','shiftTemplates','schedules','punches','reservations','maintenanceRecords','communications','crmContacts','marketingCampaigns','groupEvents','experiences','loyaltyAccounts','purchaseOrders','goodsReceipts','traceabilityRecords','productionRecords','financialEntries'];
function workContext(){try{return JSON.parse(localStorage.getItem('arcadi_work_context_v1')||'{}')}catch{return {}}}
function contextValues(){const c=workContext();return {companyId:c.companyId||'company_casa_mestres',centreId:c.centreId||''}}
function belongsToContext(item,ctx){const company=item.companyId||'company_casa_mestres',centre=item.centreId||(company==='company_casa_mestres'?'restaurant_casa_mestres':'');if(company!==ctx.companyId)return false;if(!ctx.centreId)return true;if(item.scope==='COMPANY'||item.scope==='CORPORATE')return true;return centre===ctx.centreId}
function tagForContext(item,ctx){if(!item.companyId)item.companyId=ctx.companyId;if(!item.centreId&&ctx.centreId)item.centreId=ctx.centreId;if(!item.scope)item.scope=ctx.centreId?'CENTRE':'COMPANY';return item}
function scopeData(source){if(!source)return source;const ctx=contextValues(),next={...source};for(const key of SCOPED_COLLECTIONS)next[key]=(source[key]||[]).filter(item=>belongsToContext(item,ctx));return next}
function mergeScopedData(){if(!fullData)return data;const ctx=contextValues();for(const key of SCOPED_COLLECTIONS){const current=(data[key]||[]).map(item=>tagForContext(item,ctx));const outside=(fullData[key]||[]).filter(item=>!belongsToContext(item,ctx));fullData[key]=[...outside,...current]}for(const [key,value] of Object.entries(data)){if(!SCOPED_COLLECTIONS.includes(key))fullData[key]=value}return fullData}
async function api(path,opt={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={error:t}}if(!r.ok)throw new Error(d.error||'Error '+r.status);return d}
async function load(){fullData=await api('/api/state');data=scopeData(fullData);ensureTPVData();render()}
function ensureTPVData(){data.saleItems=data.saleItems||[];data.dishes=data.dishes||[];data.dishes.forEach(d=>{if(d.onMenu==null)d.onMenu=false;if(!Array.isArray(d.zones))d.zones=[]});data.tpvConfig=data.tpvConfig||{zones:[],orders:[]};data.tpvConfig.orders=data.tpvConfig.orders||[]}
async function save(){const s=$('saveStatus');s.textContent='GUARDANT...';s.className='badge warn';try{const result=await api('/api/state',{method:'POST',body:JSON.stringify(mergeScopedData())});fullData=result.state||await api('/api/state');data=scopeData(fullData);s.textContent='GUARDAT A RENDER';s.className='badge ok';renderBrand();return data}catch(error){s.textContent='NO GUARDAT';s.className='badge bad';alert('No s’ha pogut guardar a Render: '+error.message);throw error}}
function renderBrand(){$('brandName').textContent='ARCADI GESTIO';$('brandLogo').textContent='AG'}
function show(m){active=m;location.hash=m;render()}
function render(){if(!data)return;renderBrand();$('title').textContent=titles[active]?.[0]||active;$('subtitle').textContent=titles[active]?.[1]||'';let html='';for(const [group,key,label] of menu){if(group)html+=`<div class="group">${esc(group)}</div>`;html+=`<button class="${active===key?'active':''}" onclick="show('${key}')">${esc(label)}</button>`}$('nav').innerHTML=html;const f={tpv:renderTPV,saleItems:renderSaleItems,home:renderHome,company:renderCompany,documents:renderDocuments,backup:renderBackup,suppliers:renderSuppliers,products:renderProducts,ocr:renderOCR,bases:renderBases,dishes:renderDishes,control:renderControl,employees:renderEmployees,schedules:renderSchedules,punches:renderPunches,reservations:renderReservations,permissions:renderPermissions}[active]||renderHome;f()}
window.show=show;
window.applyCoreContext=()=>{if(!fullData)return;data=scopeData(fullData);ensureTPVData();render()};
function card(key,count,title,desc){return `<div class="card" onclick="show('${key}')"><strong>${count}</strong><b>${esc(title)}</b><span>${esc(desc)}</span></div>`}
const PERMISSION_MODULES=['Horaris','Criteris de torns','Fitxatges GPS','Resum d’hores','Tasques','APPCC','Inventari'];
const PERMISSION_ACTIONS=['Consultar','Crear','Editar','Eliminar','Imprimir'];
const PERMISSION_LEVELS=['C1','C2','C3','S1','S2','S3','Runner'];
function permissionDefaults(level){const direction=level==='Direcció';return Object.fromEntries(PERMISSION_MODULES.map(m=>[m,Object.fromEntries(PERMISSION_ACTIONS.map(a=>[a,direction||(['Horaris','Tasques','APPCC','Inventari'].includes(m)&&['Consultar','Imprimir'].includes(a))]))]));}
function permissionCompanyOptions(value){return (fullData?.organizations||[]).map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}
function permissionCentreOptions(companyId,value){return (fullData?.restaurants||[]).filter(x=>x.organizationId===companyId&&x.kind!=='GROUP'&&x.status!=='Inactiu').map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}
function renderPermissions(){
 const perms=data.permissions||[], audit=data.permissionAudit||[], ctx=contextValues();
 const rows=perms.map(p=>`<tr><td>${esc(p.employeeName||p.employeeId)}</td><td>${esc(p.level||'—')}</td><td>${esc(p.centreName||p.centreId||'Tot el grup')}</td><td>${new Date(p.updatedAt||p.createdAt||Date.now()).toLocaleString('ca-ES')}</td><td><button class="btn small secondary" onclick="openPermission('${esc(p.id)}')">Editar</button></td></tr>`).join('');
 $('view').innerHTML=`<div class="notice"><b>Només Direcció:</b> aquesta pantalla és l’únic lloc on es poden concedir o retirar permisos. Els criteris de torns, els fitxatges GPS i el resum d’hores queden reservats a Direcció.</div><div class="panel"><div class="toolbar"><button class="btn" onclick="openPermission()">Nou perfil de permisos</button><button class="btn secondary" onclick="show('permissions')">Actualitzar</button></div><div class="tableWrap"><table><thead><tr><th>Empleat</th><th>Nivell</th><th>Centre</th><th>Actualitzat</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="5">Encara no hi ha permisos assignats.</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Historial de canvis</h3><div class="tableWrap"><table><thead><tr><th>Data</th><th>Acció</th><th>Empleat</th><th>Actor</th></tr></thead><tbody>${audit.slice().reverse().slice(0,20).map(x=>`<tr><td>${esc(new Date(x.at).toLocaleString('ca-ES'))}</td><td>${esc(x.action)}</td><td>${esc(x.employeeName||'')}</td><td>${esc(x.actor||'Direcció')}</td></tr>`).join('')||'<tr><td colspan="4">Sense canvis registrats.</td></tr>'}</tbody></table></div></div>`;
}
function openPermission(id=''){const p=(data.permissions||[]).find(x=>x.id===id)||{};const companyId=p.companyId||contextValues().companyId;const employee=(data.employees||[]).find(x=>x.id===p.employeeId);const level=p.level||employee?.level||'C1';const matrix=p.matrix||permissionDefaults(level);openModal(id?'Editar permisos':'Nou perfil de permisos',`<form id="permissionForm"><div class="grid"><div><label>Empresa</label><select id="perm_company">${permissionCompanyOptions(companyId)}</select></div><div><label>Centre de treball</label><select id="perm_centre">${permissionCentreOptions(companyId,p.centreId||contextValues().centreId)}</select></div><div><label>Empleat</label><select id="perm_employee">${employeeOptions(p.employeeId||'')}</select></div><div><label>Nivell</label><select id="perm_level">${['Direcció',...PERMISSION_LEVELS].map(x=>`<option ${x===level?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="tableWrap"><table><thead><tr><th>Mòdul</th>${PERMISSION_ACTIONS.map(a=>`<th>${a}</th>`).join('')}</tr></thead><tbody>${PERMISSION_MODULES.map(m=>`<tr><td><b>${m}</b></td>${PERMISSION_ACTIONS.map(a=>`<td><input type="checkbox" data-perm-module="${esc(m)}" data-perm-action="${a}" ${matrix[m]?.[a]?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn" type="submit">Guardar permisos</button><button class="btn secondary" type="button" onclick="closeModal()">Cancel·lar</button></div></form>`);document.getElementById('perm_company').onchange=e=>document.getElementById('perm_centre').innerHTML=permissionCentreOptions(e.target.value,'');document.getElementById('perm_level').onchange=e=>{const d=permissionDefaults(e.target.value);document.querySelectorAll('[data-perm-module]').forEach(i=>i.checked=Boolean(d[i.dataset.permModule]?.[i.dataset.permAction]))};document.getElementById('permissionForm').onsubmit=async e=>{e.preventDefault();const emp=document.getElementById('perm_employee').selectedOptions[0];const record={id:id||uid('perm'),companyId:document.getElementById('perm_company').value,centreId:document.getElementById('perm_centre').value,centreName:document.getElementById('perm_centre').selectedOptions[0]?.textContent||'',employeeId:document.getElementById('perm_employee').value,employeeName:emp?.textContent||'',level:document.getElementById('perm_level').value,matrix:{},updatedAt:new Date().toISOString()};PERMISSION_MODULES.forEach(m=>{record.matrix[m]={};PERMISSION_ACTIONS.forEach(a=>record.matrix[m][a]=document.querySelector(`[data-perm-module="${CSS.escape(m)}"][data-perm-action="${a}"]`)?.checked===true)});data.permissions=data.permissions||[];const ix=data.permissions.findIndex(x=>x.id===record.id);if(ix<0)data.permissions.push(record);else data.permissions[ix]=record;data.permissionAudit=data.permissionAudit||[];data.permissionAudit.push({at:new Date().toISOString(),action:id?'Actualització':'Alta',employeeName:record.employeeName,employeeId:record.employeeId,actor:'Direcció'});await save();closeModal();renderPermissions()}}
function renderHome(){$('view').innerHTML=`<div class="notice"><b>ARCADI GESTIO RESTAURANT:</b> una sola aplicació per a sala, cuina, escandalls, compres, inventari, APPCC, clients, reserves, economia i equip. La IA és una ajuda opcional.</div><div class="cards"><div class="card" onclick="ArcadiModules.hub()"><strong>67</strong><b>Gestió integral</b><span>Totes les àrees consolidades, sense duplicar dades</span></div>${card('products',data.products.length,'Productes / Magatzem','Codi, preu, unitat i família')}${card('bases',data.bases.length,'Bases de cuina','Ingredients i cost')}${card('dishes',data.dishes.length,'Fitxes de plats','Escandall incorporat')}${card('documents',data.documents.length,'Documents comercials','Cartes, menús i pressupostos')}${card('control','✓','Control Normatiu','APPCC, PRL i registres')}${card('reservations',(data.reservations||[]).length,'Reserves','Calendari, fiança i pagaments')}${card('employees',data.employees.length,'RRHH','Empleats, horaris i fitxatges')}</div>`}
function field(label,id,val='',type='text',extra=''){return `<div><label>${esc(label)}</label><input id="${id}" type="${type}" value="${esc(val)}" ${extra}></div>`}
function renderCompany(){const c=data.company||{},g=c.gps||{};$('view').innerHTML=`<div class="panel"><h3>Dades de l’empresa</h3><div class="grid">${field('Nom comercial','c_name',c.name)}${field('Raó social','c_legal',c.legal)}${field('CIF / NIF','c_tax',c.tax)}${field('Telèfon','c_phone',c.phone)}${field('Email','c_email',c.email,'email')}${field('Adreça','c_address',c.address)}</div><h3>Logotip</h3><div class="grid"><div><label>Seleccionar logotip</label><input id="c_logo_file" type="file" accept="image/*"><p class="muted">El logotip s’incorpora a les plantilles i documents.</p></div><div class="brandLogo" style="width:120px;height:90px" id="companyLogo">${c.logo?`<img src="${c.logo}">`:'Sense logo'}</div></div><h3>Zona GPS de fitxatge</h3><div class="grid3">${field('Latitud','g_lat',g.lat,'number','step="0.000001"')}${field('Longitud','g_lng',g.lng,'number','step="0.000001"')}${field('Radi autoritzat (metres)','g_radius',g.radius,'number','min="1"')}</div><div class="actions"><button class="btn" id="saveCompany">Guardar configuració</button><button class="btn secondary" onclick="window.print()">Imprimir fitxa</button></div></div>`;$('c_logo_file').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{$('companyLogo').innerHTML=`<img src="${r.result}">`;$('companyLogo').dataset.logo=r.result};r.readAsDataURL(f)};$('saveCompany').onclick=async()=>{data.company={...c,name:$('c_name').value.trim(),legal:$('c_legal').value.trim(),tax:$('c_tax').value.trim(),phone:$('c_phone').value.trim(),email:$('c_email').value.trim(),address:$('c_address').value.trim(),logo:$('companyLogo').dataset.logo||c.logo||'',gps:{lat:n($('g_lat').value),lng:n($('g_lng').value),radius:n($('g_radius').value)||60}};await save();renderCompany()}}
function toolbar(module,label){return `<div class="panel"><div class="toolbar"><button class="btn" onclick="openForm('${module}')">Nou / Crear</button><button class="btn secondary" onclick="printList('${module}')">Imprimir esborrany</button><input id="search" class="search" placeholder="Buscar..." oninput="render()"></div></div>`}
function qfilter(arr){const q=norm($('search')?.value||'');return q?arr.filter(x=>norm(JSON.stringify(x)).includes(q)):arr}
function actions(module,id){return `<button class="btn small secondary" onclick="openForm('${module}','${id}')">Editar</button> <button class="btn small bad" onclick="removeItem('${module}','${id}')">Eliminar</button>`}
function renderSuppliers(){const arr=qfilter(data.suppliers||[]);$('view').innerHTML=toolbar('suppliers')+`<div class="panel"><div class="tableWrap"><table><thead><tr><th>Proveïdor</th><th>CIF</th><th>Telèfon</th><th>Email</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td><b>${esc(x.name||x.tradeName)}</b><br><span class="muted">${esc(x.tradeName||'')}</span></td><td>${esc(x.taxId||'')}</td><td>${esc(x.phone||'')}</td><td>${esc(x.email||'')}</td><td>${actions('suppliers',x.id)}</td></tr>`).join('')||'<tr><td colspan="5">Sense proveïdors.</td></tr>'}</tbody></table></div></div>`}
function renderProducts(){const arr=qfilter(data.products||[]);$('view').innerHTML=toolbar('products')+`<div class="panel"><div class="tableWrap"><table><thead><tr><th>Codi</th><th>Producte</th><th>Família</th><th>Unitat</th><th>Preu</th><th>Stock</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.name)}</td><td>${esc(x.family)}</td><td>${esc(x.unit)}</td><td>${money(x.price)}</td><td>${esc(x.stock)} / mín. ${esc(x.min)}</td><td>${actions('products',x.id)}</td></tr>`).join('')||'<tr><td colspan="7">Sense productes.</td></tr>'}</tbody></table></div></div>`}
function renderOCR(){$('view').innerHTML=`<div class="panel"><div class="notice"><b>Funció única de l’OCR:</b> llegir el document, revisar nom/preu/unitat/família i crear o actualitzar productes al magatzem.</div><a class="btn gold" href="/ocr.html">Obrir lector OCR</a><p class="muted">No crea compres, albarans, IVA, venciments ni moviments comptables.</p></div>`}
function convertQty(qty,from,to){let v=n(qty);if(to==='kg'&&from==='g')v/=1000;if(to==='L'&&from==='ml')v/=1000;if(to==='g'&&from==='kg')v*=1000;if(to==='ml'&&from==='L')v*=1000;return v}
function ingredientQtyText(i){return i.asNeeded?(i.qtyText||'SCP'):`${i.qty} ${i.unit||''}`.trim()}
function baseYieldText(b){if(b.yield!=null&&n(b.yield)>0)return `${b.yieldApproximate?'≈ ':''}${b.yield} ${b.yieldUnit||''}`.trim();if(b.yieldMin!=null||b.yieldMax!=null)return `${b.yieldMin??'?'}–${b.yieldMax??'?'} ${b.yieldUnit||''}`.trim();return 'Pendent'}
function baseCost(b,seen=new Set()){if(!b||seen.has(b.id))return 0;const next=new Set(seen);next.add(b.id);const direct=(b.ingredients||[]).reduce((sum,i)=>sum+ingredientCost(i),0);return direct+(b.baseUses||[]).reduce((sum,i)=>{const child=data.bases.find(x=>x.id===i.baseId),yieldQty=child?.yield!=null?n(child.yield):0;if(!child||!yieldQty)return sum;return sum+baseCost(child,next)*(convertQty(i.qty,i.unit,child.yieldUnit)/yieldQty)},0)}
function dishCost(d){return (d.ingredients||[]).reduce((sum,i)=>sum+ingredientCost(i),0)+(d.baseUses||[]).reduce((sum,i)=>{const b=data.bases.find(x=>x.id===i.baseId),yieldQty=b?.yield!=null?n(b.yield):0;if(!b||!yieldQty)return sum;return sum+baseCost(b)*(convertQty(i.qty,i.unit,b.yieldUnit)/yieldQty)},0)}
function ingredientCost(i){if(i.asNeeded)return 0;const p=data.products.find(x=>x.id===i.productId);if(!p)return 0;return convertQty(i.qty,i.unit||p.unit,p.unit)*n(p.price)}
function renderBases(){const arr=qfilter(data.bases||[]);$('view').innerHTML=toolbar('bases')+`<div class="panel"><div class="tableWrap"><table><thead><tr><th>Base</th><th>Tipus</th><th>Rendiment</th><th>Cost</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td><b>${esc(x.name)}</b>${x.sourceFile?`<br><span class="muted">Fitxa ${esc(x.sourceFile)}</span>`:''}</td><td>${esc(x.type||'')}</td><td>${esc(baseYieldText(x))}</td><td>${money(baseCost(x))}</td><td>${actions('bases',x.id)} <button class="btn small gold" onclick="printSingle('bases','${x.id}')">Fitxa</button></td></tr>`).join('')||'<tr><td colspan="5">Sense bases.</td></tr>'}</tbody></table></div></div>`}
function renderDishes(){const arr=qfilter(data.dishes||[]);$('view').innerHTML=toolbar('dishes')+`<div class="panel"><div class="notice"><b>Front Office:</b> no es crea cap catàleg duplicat. Un plat apareix al TPV quan té <b>A la carta = Sí</b> i està assignat a la zona.</div><div class="tableWrap"><table><thead><tr><th>Plat</th><th>Categoria</th><th>Venda</th><th>A la carta</th><th>Zones</th><th>Cost / escandall</th><th>% cost</th><th></th></tr></thead><tbody>${arr.map(x=>{const c=dishCost(x),pct=n(x.sale)?c/n(x.sale)*100:0;return `<tr><td><b>${esc(x.name)}</b>${x.recipeStatus?`<br><span class="badge ${x.recipeStatus.includes('VALIDADA')?'ok':'warn'}">${esc(x.recipeStatus)}</span>`:''}</td><td>${esc(x.cat||'')}</td><td>${money(x.sale)}</td><td>${x.onMenu?'<span class="badge ok">Sí</span>':'No'}</td><td>${esc(zoneNames(x.zones).join(', ')||'—')}</td><td>${money(c)}</td><td>${pct.toFixed(1)}%</td><td>${actions('dishes',x.id)} <button class="btn small gold" onclick="printSingle('dishes','${x.id}')">Fitxa</button></td></tr>`}).join('')||'<tr><td colspan="8">Sense plats.</td></tr>'}</tbody></table></div></div>`}
function documentTemplateOptions(value='elegant'){return [['elegant','Elegant'],['classic','Clàssica'],['minimal','Minimalista']].map(([id,label])=>`<option value="${id}" ${id===value?'selected':''}>${label}</option>`).join('')}
function documentTemplateLabel(value){return ({elegant:'Elegant',classic:'Clàssica',minimal:'Minimalista'})[value]||'Elegant'}
function renderDocuments(){const arr=qfilter(data.documents||[]);$('view').innerHTML=toolbar('documents')+`<div class="notice"><b>Plantilles de disseny:</b> cada carta, menú o pressupost pot usar una plantilla diferent i un color corporatiu. Es pot canviar en qualsevol moment sense perdre el contingut.<br><b>Menús de la mini app de reserves:</b> edita un document de tipus Menú i activa "Publicar a reserves".</div><div class="panel"><div class="tableWrap"><table><thead><tr><th>Tipus</th><th>Títol</th><th>Plantilla</th><th>Preu</th><th>Reserves</th><th>Fiança</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td>${esc(x.type)}</td><td><b>${esc(x.title)}</b><br><span class="muted">${esc(x.client||'')} ${esc(x.date||'')}</span></td><td><span class="badge">${esc(documentTemplateLabel(x.designTemplate))}</span></td><td>${x.type==='Menú'&&x.publishReservations?money(x.reservationPrice||0):esc(x.price||'')}</td><td>${x.type==='Menú'?(x.publishReservations?'PUBLICAT':'No publicat'):'—'}</td><td>${x.type==='Menú'&&x.publishReservations?(x.depositType==='percent'?esc(x.depositValue||0)+'%':money(x.depositValue||0)+'/pax'):'—'}</td><td>${actions('documents',x.id)} <button class="btn small secondary" onclick="printSingle('documents','${x.id}','draft')">Esborrany</button> <button class="btn small gold" onclick="printSingle('documents','${x.id}','premium')">Disseny</button></td></tr>`).join('')||'<tr><td colspan="7">Sense documents.</td></tr>'}</tbody></table></div></div>`}
function renderReservations(){const all=[...(data.reservations||[])].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)),cfg=data.reservationConfig||{},arr=all.filter(r=>String(r.date||'').startsWith(reservationMonth)),byDate={};arr.forEach(r=>(byDate[r.date]??=[]).push(r));const days=Object.keys(byDate).sort(),monthLabel=new Date(reservationMonth+'-01T12:00:00').toLocaleDateString('ca-ES',{month:'long',year:'numeric'});$('view').innerHTML=`<div class="panel"><div class="toolbar"><a class="btn gold" href="/reserves.html" target="_blank">Obrir mini app pública de reserves</a><button class="btn secondary" onclick="printList('reservations')">Imprimir llistat</button></div><div class="grid" style="margin-top:12px"><div>${field('Màxim reserva online (pax)','r_max',cfg.maxPax||10,'number','min="1"')}</div><div>${field('Telèfon grups','r_group_phone',cfg.groupPhone||data.company?.phone||'')}</div></div><div><label>Condicions de cancel·lació</label><textarea id="r_policy">${esc(cfg.cancellationPolicy||'')}</textarea></div><div class="notice"><b>Stripe:</b> <span id="stripeStatus">Comprovant connexió…</span>. La clau es configura de manera segura a Render.</div><div class="actions"><button class="btn" id="saveResCfg">Guardar configuració reserves</button></div></div><div class="panel"><div class="toolbar"><button class="btn secondary" onclick="changeReservationMonth(-1)">← Mes anterior</button><h3 style="margin:8px auto;text-transform:capitalize">${esc(monthLabel)}</h3><button class="btn secondary" onclick="changeReservationMonth(1)">Mes següent →</button></div><div class="reservationCalendar">${days.map(d=>`<div class="calendarDay"><b>${esc(new Date(d+'T12:00:00').toLocaleDateString('ca-ES',{day:'2-digit',month:'short'}))}</b><strong>${byDate[d].reduce((s,r)=>s+n(r.pax),0)} pax</strong><span>${byDate[d].length} reserves</span></div>`).join('')||'<span class="muted">Sense reserves aquest mes.</span>'}</div></div><div class="panel"><div class="tableWrap"><table><thead><tr><th>Data / hora</th><th>Client</th><th>Pax</th><th>Menú</th><th>Fiança</th><th>Pagament</th><th>Estat</th></tr></thead><tbody>${arr.map(r=>`<tr><td><b>${esc(r.date)}</b> ${esc(r.time)}</td><td>${esc(r.name)}<br><span class="muted">${esc(r.phone)} · ${esc(r.email||'')}</span></td><td>${esc(r.pax)}</td><td>${esc(r.menuTitle||'')}</td><td>${money(r.depositAmount)}</td><td>${esc(r.paymentStatus||'pendent')}</td><td><select data-res-status="${r.id}">${['Pendent Stripe','Pendent pagament','Confirmada','Cancel·lada'].map(x=>`<option ${x===(r.status||'')?'selected':''}>${x}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td colspan="7">Sense reserves aquest mes.</td></tr>'}</tbody></table></div></div>`;api('/api/health').then(h=>{$('stripeStatus').textContent=h.stripeConfigured?'ACTIVAT':'NO CONFIGURAT';$('stripeStatus').style.fontWeight='800'}).catch(()=>{$('stripeStatus').textContent='No disponible'});$('saveResCfg').onclick=async()=>{const updated={maxPax:n($('r_max').value)||10,groupPhone:$('r_group_phone').value.trim(),cancellationPolicy:$('r_policy').value.trim(),currency:'EUR'};await api('/api/reservation-config',{method:'PUT',body:JSON.stringify(updated)});data.reservationConfig={...cfg,...updated};renderReservations()};document.querySelectorAll('[data-res-status]').forEach(el=>el.onchange=async()=>{const result=await api('/api/reservations/'+encodeURIComponent(el.dataset.resStatus)+'/status',{method:'PUT',body:JSON.stringify({status:el.value})});const i=(data.reservations||[]).findIndex(x=>x.id===el.dataset.resStatus);if(i>=0)data.reservations[i]=result.reservation;renderReservations()})}
window.changeReservationMonth=delta=>{const d=new Date(reservationMonth+'-01T12:00:00');d.setMonth(d.getMonth()+delta);reservationMonth=d.toISOString().slice(0,7);renderReservations()};
function renderControl(){$('view').innerHTML=`<div class="panel"><div class="notice">Eina completa incorporada: APPCC, zones, neteja, temperatures, incidències, PRL, EPIs, formació, impressió i exportació.</div><iframe class="iframe" src="/control_normatiu.html"></iframe></div>`}
function renderEmployees(){const arr=qfilter(data.employees||[]);$('view').innerHTML=toolbar('employees')+`<div class="panel"><div class="notice">La miniapp es vincula al mòbil mitjançant un codi d’activació d’un sol ús. No cal PIN permanent.</div><div class="tableWrap"><table><thead><tr><th>Codi</th><th>Nom</th><th>Nivell</th><th>Funció</th><th>Dispositiu</th><th>Actiu</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.name)}<br><span class="muted">${esc(x.phone||'Sense telèfon')}</span></td><td>${esc(x.level||'—')}</td><td>${esc(x.role||x.roleBase||'')}</td><td>${x.deviceActivatedAt?'<span class="badge ok">Vinculat</span>':'<span class="badge warn">No activat</span>'}</td><td>${x.active===false?'No':'Sí'}</td><td>${actions('employees',x.id)} <button class="btn small gold" onclick="generateDeviceActivation('${x.id}')">Activar mòbil</button> ${x.deviceActivatedAt?`<button class="btn small bad" onclick="unlinkEmployeeDevice('${x.id}')">Desvincular</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7">Sense empleats.</td></tr>'}</tbody></table></div></div>`}
async function generateDeviceActivation(id){const employee=(data.employees||[]).find(x=>x.id===id);if(!employee)return;if(!employee.phone&&!confirm('Aquest empleat no té telèfon informat. Vols generar igualment el codi?'))return;const result=await api(`/api/employees/${encodeURIComponent(id)}/device-activation`,{method:'POST',body:'{}'});const url=location.origin+'/fitxatges.html';const message=`ARCADI GESTIO · Activació de ${employee.name}\nCodi d’empleat: ${employee.code}\nCodi d’activació: ${result.code}\nObre: ${url}\nCaduca en 24 hores i només es pot utilitzar una vegada.`;openModal('Activació del mòbil',`<div class="notice"><b>${esc(employee.name)}</b><br>Envia aquest missatge només al seu telèfon: <b>${esc(employee.phone||'sense número')}</b></div><div class="activationCode">${esc(result.code)}</div><textarea id="activationMessage" rows="7">${esc(message)}</textarea><div class="actions"><button class="btn" onclick="copyActivationMessage()">Copiar missatge</button><button class="btn secondary" onclick="closeModal()">Tancar</button></div>`)}
async function copyActivationMessage(){const text=$('activationMessage').value;try{await navigator.clipboard.writeText(text);alert('Missatge copiat. Ja el pots enviar per WhatsApp.')}catch{$('activationMessage').select();document.execCommand('copy');alert('Missatge copiat.')}}
async function unlinkEmployeeDevice(id){if(!confirm('Desvincular aquest mòbil? L’empleat no podrà tornar a entrar fins que generis una activació nova.'))return;await api(`/api/employees/${encodeURIComponent(id)}/device-unlink`,{method:'POST',body:'{}'});await load();show('employees')}
Object.assign(window,{generateDeviceActivation,copyActivationMessage,unlinkEmployeeDevice});

let scheduleWeekStart='',scheduleWeekDirty=false;
function mondayISO(value=new Date()){const d=new Date(value);d.setHours(12,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.toISOString().slice(0,10)}
function isoPlus(iso,days){const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function shiftScheduleWeek(days){if(scheduleWeekDirty&&!confirm('Hi ha canvis de setmana sense guardar. Vols continuar?'))return;scheduleWeekDirty=false;scheduleWeekStart=isoPlus(scheduleWeekStart||mondayISO(),days);renderSchedules()}
function shiftTemplates(){data.shiftTemplates=data.shiftTemplates||[];return data.shiftTemplates}
function scheduleFor(employeeId,date){return (data.schedules||[]).find(x=>x.employeeId===employeeId&&x.date===date)}
function shiftTimeText(item){return item&&item.start&&item.end?`${item.start}–${item.end}`:'Descans'}
function setWeeklyShift(employeeId,date,value){data.schedules=data.schedules||[];const index=data.schedules.findIndex(x=>x.employeeId===employeeId&&x.date===date);if(value==='__exception__'){openScheduleException(employeeId,date);return}if(!value){if(index>=0)data.schedules.splice(index,1)}else{const template=shiftTemplates().find(x=>x.id===value),employee=data.employees.find(x=>x.id===employeeId);if(!template||!employee)return;const item=index>=0?data.schedules[index]:{id:uid('sche'),employeeId,date};Object.assign(item,{employeeId,employeeName:employee.name,date,start:template.start,end:template.end,area:template.area||'',notes:template.notes||'',shiftTemplateId:template.id,shiftCode:template.code,exception:false});if(index<0)data.schedules.push(item)}scheduleWeekDirty=true;renderSchedules()}
function newScheduleFor(employeeId,date){openScheduleException(employeeId,date)}
function openScheduleException(employeeId,date){const existing=scheduleFor(employeeId,date);openForm('schedules',existing?.id||null);$('f_employee').value=employeeId;$('f_date').value=date;const title=document.querySelector('.modal h2');if(title)title.textContent='Excepció individual';editing.scheduleException=true}
async function saveScheduleWeek(){await save();scheduleWeekDirty=false;renderSchedules()}
function openShiftCriteria(){const rows=shiftTemplates().map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.name||'')}</td><td>${esc(x.start)}–${esc(x.end)}</td><td>${esc(x.area||'')}</td><td><button class="btn small" onclick="openShiftCriterion('${x.id}')">Editar</button> <button class="btn bad small" onclick="removeShiftCriterion('${x.id}')">Eliminar</button></td></tr>`).join('');openModal('Criteris de torns',`<div class="notice">Defineix aquí els torns A, B, C… Una modificació s’aplica als nous quadrants; els horaris ja guardats conserven les hores assignades.</div><div class="toolbar"><button class="btn gold" onclick="openShiftCriterion()">+ Nou torn</button></div><div class="tableWrap"><table><thead><tr><th>Codi</th><th>Nom</th><th>Horari</th><th>Àrea</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="5">Encara no hi ha criteris de torn.</td></tr>'}</tbody></table></div>`)}
function openShiftCriterion(id=''){const o=shiftTemplates().find(x=>x.id===id)||{};openModal(id?'Editar criteri de torn':'Nou criteri de torn',`<div class="grid">${field('Codi (A, B, C...)','st_code',o.code||'')}${field('Nom','st_name',o.name||'')}${field('Entrada','st_start',o.start||'08:00','time')}${field('Sortida','st_end',o.end||'16:30','time')}${field('Àrea / observació','st_area',o.area||'')}</div><div><label>Notes</label><textarea id="st_notes">${esc(o.notes||'')}</textarea></div><div class="actions"><button class="btn" onclick="saveShiftCriterion('${id}')">Guardar criteri</button><button class="btn secondary" onclick="openShiftCriteria()">Cancel·lar</button></div>`)}
async function saveShiftCriterion(id=''){const code=$('st_code').value.trim().toUpperCase(),name=$('st_name').value.trim(),start=$('st_start').value,end=$('st_end').value;if(!code||!start||!end)return alert('Cal indicar codi, entrada i sortida.');if(shiftTemplates().some(x=>x.id!==id&&norm(x.code)===norm(code)))return alert('Aquest codi de torn ja existeix.');let o=shiftTemplates().find(x=>x.id===id);if(!o){o={id:uid('shift')};data.shiftTemplates.push(o)}Object.assign(o,{code,name,start,end,area:$('st_area').value.trim(),notes:$('st_notes').value.trim()});await save();openShiftCriteria()}
async function removeShiftCriterion(id){if(!confirm('Eliminar aquest criteri de torn? Els horaris ja guardats conservaran les hores.'))return;data.shiftTemplates=shiftTemplates().filter(x=>x.id!==id);await save();openShiftCriteria()}
function printScheduleWeek(){const days=Array.from({length:7},(_,i)=>isoPlus(scheduleWeekStart,i)),names=['Dilluns','Dimarts','Dimecres','Dijous','Divendres','Dissabte','Diumenge'],employees=(data.employees||[]).filter(x=>x.active!==false);const rows=employees.map(e=>`<tr><td><b>${esc(e.level||'')}</b><br>${esc(e.name)}</td>${days.map(day=>{const s=scheduleFor(e.id,day);return `<td>${s?`<b>${esc(s.shiftCode||'EXC')}</b><br>${esc(shiftTimeText(s))}`:'Descans'}</td>`}).join('')}</tr>`).join('');printHTML(`<div class="draftDoc">${printHeader('Quadrant setmanal')}<h2>Setmana del ${esc(scheduleWeekStart)}</h2><table><thead><tr><th>Plantilla</th>${days.map((d,i)=>`<th>${names[i]}<br>${esc(d.slice(5))}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`)}
Object.assign(window,{shiftScheduleWeek,setWeeklyShift,newScheduleFor,openScheduleException,saveScheduleWeek,openShiftCriteria,openShiftCriterion,saveShiftCriterion,removeShiftCriterion,printScheduleWeek});
function renderSchedules(){if(!scheduleWeekStart)scheduleWeekStart=mondayISO();shiftTemplates();const all=data.schedules||[],days=Array.from({length:7},(_,i)=>isoPlus(scheduleWeekStart,i)),employees=(data.employees||[]).filter(x=>x.active!==false),dayNames=['Dl','Dt','Dc','Dj','Dv','Ds','Dg'];const options=s=>`<option value="">Descans</option>${shiftTemplates().map(t=>`<option value="${t.id}" ${s?.shiftTemplateId===t.id?'selected':''}>Torn ${esc(t.code)}</option>`).join('')}<option value="__exception__" ${s&&!s.shiftTemplateId?'selected':''}>Excepció individual</option>`;const matrix=employees.map(e=>`<tr><td><b>${esc(e.level||'—')} · ${esc(e.name)}</b><br><span class="muted">${esc(e.role||'')}</span></td>${days.map(day=>{const s=scheduleFor(e.id,day);return `<td><select class="shiftSelect" onchange="setWeeklyShift('${e.id}','${day}',this.value)">${options(s)}</select><div class="shiftHours ${s?.exception?'exception':''}">${esc(shiftTimeText(s))}</div>${s?.exception?`<button class="linkBtn" onclick="openScheduleException('${e.id}','${day}')">Editar excepció</button>`:''}</td>`}).join('')}</tr>`).join('');$('view').innerHTML=`<div class="panel"><div class="toolbar"><button class="btn gold" onclick="saveScheduleWeek()">Guardar setmana</button><button class="btn" onclick="openShiftCriteria()">Criteris de torns</button><button class="btn secondary" onclick="shiftScheduleWeek(-7)">← Setmana anterior</button><button class="btn secondary" onclick="shiftScheduleWeek(7)">Setmana següent →</button><button class="btn secondary" onclick="scheduleWeekStart=mondayISO();scheduleWeekDirty=false;renderSchedules()">Avui</button><button class="btn secondary" onclick="printScheduleWeek()">Imprimir quadrant</button></div><h3>Horari setmanal · setmana del ${esc(scheduleWeekStart)}</h3><p class="muted">Tots els empleats actius apareixen automàticament. Assigna un criteri de torn o crea una excepció individual.</p><div class="tableWrap"><table class="weeklySchedule"><thead><tr><th>Posició / empleat</th>${days.map((day,i)=>`<th>${dayNames[i]}<br>${esc(day.slice(5))}</th>`).join('')}</tr></thead><tbody>${matrix||'<tr><td colspan="8">No hi ha empleats actius.</td></tr>'}</tbody></table></div></div>`}
function renderPunches(){const arr=[...(data.punches||[])].sort((a,b)=>String(b.dateTime).localeCompare(String(a.dateTime)));$('view').innerHTML=`<div class="panel"><div class="toolbar"><a class="btn gold" href="/fitxatges.html">Obrir app de fitxatge</a><button class="btn secondary" onclick="printList('punches')">Imprimir registre</button></div></div><div class="panel"><div class="tableWrap"><table><thead><tr><th>Data i hora</th><th>Empleat</th><th>Acció</th><th>GPS</th><th>Distància</th></tr></thead><tbody>${arr.map(x=>`<tr><td>${new Date(x.dateTime).toLocaleString('ca-ES')}</td><td>${esc(x.employeeName)}</td><td><b>${esc(x.type)}</b></td><td>${esc(x.status)}</td><td>${x.distance==null?'—':esc(x.distance)+' m'}</td></tr>`).join('')||'<tr><td colspan="5">Sense fitxatges.</td></tr>'}</tbody></table></div></div>`}
function renderBackup(){$('view').innerHTML=`<div class="panel"><h3>Còpia completa</h3><p>Inclou empresa, magatzem, cuina, documents, RRHH i Control Normatiu.</p><div class="actions"><a class="btn" href="/api/backup">Descarregar còpia JSON</a><label class="btn secondary">Restaurar còpia<input id="restoreFile" type="file" accept=".json" style="display:none"></label></div><p class="muted">Abans de cada guardat, el servidor conserva una còpia automàtica dins la carpeta backups.</p></div>`;$('restoreFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{const d=JSON.parse(r.result);await api('/api/restore',{method:'POST',body:JSON.stringify(d)});alert('Còpia restaurada.');await load()}catch(err){alert(err.message)}};r.readAsText(f)}}
function famOptions(v){return (data.config.families||[]).map(f=>`<option ${f.name===v?'selected':''}>${esc(f.name)}</option>`).join('')}
function unitOptions(v){return (data.config.units||[]).map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function supplierOptions(v){return `<option value="">—</option>`+(data.suppliers||[]).map(x=>`<option value="${x.id}" ${x.id===v?'selected':''}>${esc(x.name||x.tradeName)}</option>`).join('')}
function employeeOptions(v){return (data.employees||[]).map(x=>`<option value="${x.id}" ${x.id===v?'selected':''}>${esc(x.code)} · ${esc(x.name)}</option>`).join('')}
function centreOptions(v){const ctx=contextValues();return (fullData?.restaurants||data.restaurants||[]).filter(x=>x.organizationId===ctx.companyId&&x.kind!=='GROUP'&&x.status!=='Inactiu').map(x=>`<option value="${x.id}" ${x.id===v?'selected':''}>${esc(x.name)}</option>`).join('')}
function productOptions(v){return `<option value="">Selecciona...</option>`+(data.products||[]).map(x=>`<option value="${x.id}" ${x.id===v?'selected':''}>${esc(x.code)} · ${esc(x.name)}</option>`).join('')}
function baseOptions(v){return `<option value="">Selecciona...</option>`+(data.bases||[]).map(x=>`<option value="${x.id}" ${x.id===v?'selected':''}>${esc(x.name)}</option>`).join('')}
function nextCode(fam){const def=(data.config.families||[]).find(x=>x.name===fam)||{prefix:'ALT'};let max=0;(data.products||[]).forEach(p=>{const m=String(p.code||'').match(new RegExp('^'+def.prefix+'-(\\d+)$','i'));if(m)max=Math.max(max,Number(m[1]))});return def.prefix+'-'+String(max+1).padStart(3,'0')}
function openModal(title,html){document.querySelector('.modal')?.classList.remove('posModal');$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modalBg').classList.add('open')}
window.closeModal=()=>{$('modalBg').classList.remove('open');document.querySelector('.modal')?.classList.remove('posModal');editing=null;temp={ingredients:[],baseUses:[]}}
window.openForm=(module,id=null)=>{editing={module,id};const arr=data[module]||[],o=id?arr.find(x=>x.id===id):{};if(id&&!o)return alert('Registre no trobat');if(module==='suppliers')openModal(id?'Editar proveïdor':'Nou proveïdor',`<div class="grid">${field('Nom','f_name',o.name||'')}${field('Nom comercial','f_trade',o.tradeName||'')}${field('CIF / NIF','f_tax',o.taxId||'')}${field('Telèfon','f_phone',o.phone||'')}${field('Email','f_email',o.email||'','email')}${field('Adreça / població','f_address',o.address||o.postalCity||'')}</div>${saveBtn()}`);
 if(module==='products')openModal(id?'Editar producte':'Nou producte',`<div class="grid">${field('Codi intern','f_code',o.code||'')}${field('Nom del producte','f_name',o.name||'')}<div><label>Família</label><select id="f_family">${famOptions(o.family||'Altres')}</select></div><div><label>Unitat</label><select id="f_unit">${unitOptions(o.unit||'unitat')}</select></div>${field('Preu de compra','f_price',o.price||0,'number','step="0.001" min="0"')}${field('Stock','f_stock',o.stock||0,'number','step="0.001"')}${field('Stock mínim','f_min',o.min||0,'number','step="0.001"')}<div><label>Proveïdor</label><select id="f_supplier">${supplierOptions(o.supplierId||'')}</select></div>${field('Ubicació','f_location',o.location||'')}</div><div><label>Notes</label><textarea id="f_notes">${esc(o.notes||'')}</textarea></div>${saveBtn()}`);
 if(module==='bases'){temp.ingredients=JSON.parse(JSON.stringify(o.ingredients||[]));temp.baseUses=JSON.parse(JSON.stringify(o.baseUses||[]));openModal(id?'Editar base':'Nova base',`${o.sourceFile?`<div class="notice">Origen: fitxa manuscrita ${esc(o.sourceFile)}. Les dades pendents no s’han inventat.</div>`:''}<div class="grid">${field('Nom','f_name',o.name||'')}${field('Tipus','f_type',o.type||'')}${field('Partida','f_station',o.station||'')}${field('Quantitat inicial / anotació','f_initial',o.initialQtyText||(o.initialQty!=null?`${o.initialQty} ${o.initialUnit||''}`.trim():''))}${field('Rendiment exacte','f_yield',o.yield??'','number','step="0.001" min="0"')}${field('Rendiment mínim','f_yieldMin',o.yieldMin??'','number','step="0.001" min="0"')}${field('Rendiment màxim','f_yieldMax',o.yieldMax??'','number','step="0.001" min="0"')}<div><label>Unitat rendiment</label><select id="f_yieldUnit">${unitOptions(o.yieldUnit||'L')}</select></div>${field('Format d’envasat','f_pack',o.packText||'')}${field('Caducitat / vida útil','f_life',o.life||'')}${field('Conservació','f_conservation',o.conservation||'')}</div><h3>Productes directes</h3><div id="ingredientRows" class="lineRows"></div><button class="btn secondary" onclick="addIngredient()">+ Producte</button><h3>Altres bases utilitzades</h3><div id="baseRows" class="lineRows"></div><button class="btn secondary" onclick="addBaseUse()">+ Base</button><div><label>Procés</label><textarea id="f_process">${esc(o.process||'')}</textarea></div>${o.transcriptionNotes?`<div class="notice"><b>Pendent de revisió:</b> ${esc(o.transcriptionNotes)}</div>`:''}${saveBtn()}`);renderIngredientRows();renderBaseRows()}
 if(module==='dishes'){temp.ingredients=JSON.parse(JSON.stringify(o.ingredients||[]));temp.baseUses=JSON.parse(JSON.stringify(o.baseUses||[]));openModal(id?'Editar fitxa de plat':'Nova fitxa de plat',`${o.recipeStatus?`<div class="notice"><b>${esc(o.recipeStatus)}</b>: revisa ingredients, gramatges i procés. En guardar la fitxa quedarà com a recepta revisada.</div>`:''}<div class="grid3">${field('Nom del plat','f_name',o.name||'')}${field('Categoria','f_cat',o.cat||'')}${field('Partida','f_station',o.station||'')}${field('Preu de venda','f_sale',o.sale||0,'number','step="0.01"')}${field('Racions','f_servings',o.servings||1,'number','step="1"')}${field('Al·lèrgens','f_allergens',o.allergens||'')}</div><div class="tpvPublish"><div><label>A la carta / Front Office</label><select id="f_onmenu"><option value="false" ${o.onMenu?'':'selected'}>No</option><option value="true" ${o.onMenu?'selected':''}>Sí</option></select></div><div><label>Zones on s'ofereix</label><div class="zoneChecks">${zoneChecks(o.zones||[])}</div></div></div><div><label>Descripció</label><textarea id="f_desc">${esc(o.desc||'')}</textarea></div><h3>Productes directes</h3><div id="ingredientRows" class="lineRows"></div><button class="btn secondary" onclick="addIngredient()">+ Producte</button><h3>Bases de cuina</h3><div id="baseRows" class="lineRows"></div><button class="btn secondary" onclick="addBaseUse()">+ Base</button><div class="grid"><div><label>Elaboració</label><textarea id="f_process">${esc(o.process||'')}</textarea></div><div><label>Acabat i emplatat</label><textarea id="f_plating">${esc(o.plating||'')}</textarea></div></div><div class="okBox"><b>Cost calculat:</b> <span id="costPreview">0,00 €</span>. Aquest càlcul forma part de la fitxa; no hi ha mòdul d’escandalls separat.</div>${saveBtn()}`);renderIngredientRows();renderBaseRows();updateCostPreview()}
 if(module==='saleItems')openModal(id?'Editar article de venda':'Nou article de venda',`<div class="grid3">${field('Nom','f_name',o.name||'')}${field('Família','f_cat',o.family||'')}${field('Preu base','f_sale',o.price||0,'number','step="0.01"')}<div><label>A la carta / Front Office</label><select id="f_onmenu"><option value="false" ${o.onMenu?'':'selected'}>No</option><option value="true" ${o.onMenu?'selected':''}>Sí</option></select></div><div><label>Zones on s'ofereix</label><div class="zoneChecks">${zoneChecks(o.zones||[])}</div></div></div>${o.source==='agora-260816'?`<div class="notice"><b>Origen Ágora</b> · Format ${esc(o.sourceSaleFormatId)} · Producte ${esc(o.sourceProductId)}<br>Barra: ${money(o.sourcePrices?.Barra)} · Sala: ${money(o.sourcePrices?.Sala)} · Terrassa: ${money(o.sourcePrices?.Terraza)}</div>`:''}${saveBtn()}`);
 if(module==='documents'){const checked=new Set(o.items||[]);openModal(id?'Editar document':'Nou document',`<div class="grid"><div><label>Tipus</label><select id="f_type">${['Carta','Menú','Pressupost','Proposta de grup'].map(x=>`<option ${x===(o.type||'Menú')?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Plantilla de disseny</label><select id="f_design_template">${documentTemplateOptions(o.designTemplate||'elegant')}</select></div>${field('Color corporatiu','f_accent_color',o.accentColor||'#9b7a3d','color')}${field('Títol','f_title',o.title||'')}${field('Subtítol','f_subtitle',o.subtitle||'')}${field('Client / grup','f_client',o.client||'')}${field('Data','f_date',o.date||new Date().toISOString().slice(0,10),'date')}${field('Preu / import','f_price',o.price||'')}</div><h3>Plats incorporats</h3><div class="panel" style="box-shadow:none;max-height:260px;overflow:auto">${data.dishes.map(d=>`<label style="display:block"><input class="dishCheck" type="checkbox" value="${d.id}" ${checked.has(d.id)?'checked':''}> ${esc(d.name)}</label>`).join('')||'Primer crea fitxes de plats.'}</div><div class="grid"><div><label>Condicions / notes</label><textarea id="f_notes">${esc(o.notes||'')}</textarea></div><div><label>Peu del document</label><textarea id="f_footer">${esc(o.footer||'')}</textarea></div></div><h3>Publicació a la mini app de reserves</h3><div class="notice">Aquests camps només s’apliquen si el tipus és <b>Menú</b>.</div><div class="grid3"><div><label>Publicar a reserves</label><select id="f_publish_res"><option value="false" ${o.publishReservations?'':'selected'}>No</option><option value="true" ${o.publishReservations?'selected':''}>Sí</option></select></div>${field('Preu per persona (€)','f_res_price',o.reservationPrice||0,'number','step="0.01" min="0"')}<div><label>Tipus de fiança</label><select id="f_dep_type"><option value="fixed" ${(o.depositType||'fixed')==='fixed'?'selected':''}>€ per persona</option><option value="percent" ${o.depositType==='percent'?'selected':''}>% del preu</option></select></div>${field('Fiança (€/pax o %)','f_dep_value',o.depositValue||0,'number','step="0.01" min="0"')}</div><div><label>Text visible a reserves</label><textarea id="f_public_notes">${esc(o.publicReservationNotes||'')}</textarea></div>${saveBtn()}`)}
 if(module==='employees')openModal(id?'Editar empleat':'Nou empleat',`<div class="grid">${field('Codi','f_code',o.code||nextEmployeeCode())}${field('Nom i cognoms','f_name',o.name||'')}${field('Funció','f_role',o.role||o.roleBase||'')}<div><label>Nivell professional</label><select id="f_level">${['','C1','C2','C3','S1','S2','S3','Runner'].map(x=>`<option ${x===(o.level||'')?'selected':''}>${x||'Sense assignar'}</option>`).join('')}</select></div><div><label>Centre de treball</label><select id="f_centre" required><option value="">Selecciona centre</option>${centreOptions(o.centreId||contextValues().centreId)}</select></div>${field('Telèfon','f_phone',o.phone||'','tel')}<div><label>Actiu</label><select id="f_active"><option ${o.active!==false?'selected':''}>Sí</option><option ${o.active===false?'selected':''}>No</option></select></div></div><div class="grid"><div><label>Tasques assignades</label><textarea id="f_tasks">${esc(o.tasks||'')}</textarea></div><div><label>Responsabilitats i controls</label><textarea id="f_responsibilities">${esc(o.responsibilities||'')}</textarea></div></div><div><label>Notes</label><textarea id="f_notes">${esc(o.notes||'')}</textarea></div>${saveBtn()}`)
 if(module==='schedules')openModal(id?'Editar horari':'Nou horari',`<div class="grid"><div><label>Empleat</label><select id="f_employee">${employeeOptions(o.employeeId||'')}</select></div>${field('Data','f_date',o.date||new Date().toISOString().slice(0,10),'date')}${field('Entrada','f_start',o.start||'09:00','time')}${field('Sortida','f_end',o.end||'17:00','time')}${field('Àrea / partida','f_area',o.area||'')}</div><div><label>Notes</label><textarea id="f_notes">${esc(o.notes||'')}</textarea></div>${saveBtn()}`)
}
function saveBtn(){return `<div class="actions" style="margin-top:14px"><button class="btn" onclick="saveForm()">Guardar</button><button class="btn secondary" onclick="closeModal()">Cancel·lar</button></div>`}
function nextEmployeeCode(){let max=0;(data.employees||[]).forEach(e=>max=Math.max(max,Number(e.code)||0));return String(max+1).padStart(3,'0')}
window.addIngredient=()=>{temp.ingredients.push({productId:'',name:'',qty:0,unit:'g'});renderIngredientRows();updateCostPreview()}
window.addBaseUse=()=>{temp.baseUses.push({baseId:'',name:'',qty:0,unit:'L'});renderBaseRows();updateCostPreview()}
function renderIngredientRows(){const el=$('ingredientRows');if(!el)return;el.innerHTML=temp.ingredients.map((i,ix)=>`<div class="lineRow"><div><label>Producte</label><select data-ing="productId" data-i="${ix}">${productOptions(i.productId)}</select></div><div><label>Quantitat</label><input data-ing="qty" data-i="${ix}" type="number" step="0.001" value="${i.asNeeded?'':n(i.qty)}" ${i.asNeeded?'disabled':''}><label style="font-weight:400;margin-top:5px"><input data-ing="asNeeded" data-i="${ix}" type="checkbox" ${i.asNeeded?'checked':''}> SCP</label></div><div><label>Unitat</label><select data-ing="unit" data-i="${ix}">${unitOptions(i.unit||'g')}</select></div><button class="btn bad small" onclick="removeIngredient(${ix})">×</button></div>`).join('')||'<div class="muted" style="padding:10px">Sense ingredients.</div>';el.querySelectorAll('[data-ing]').forEach(x=>x.oninput=e=>{const ix=Number(e.target.dataset.i),k=e.target.dataset.ing,item=temp.ingredients[ix];if(k==='qty')item.qty=n(e.target.value);else if(k==='asNeeded'){item.asNeeded=e.target.checked;item.qtyText=item.asNeeded?'SCP':'';if(item.asNeeded)item.qty=0;renderIngredientRows()}else item[k]=e.target.value;if(k==='productId'){const p=data.products.find(x=>x.id===e.target.value);item.name=p?.name||'';if(p)item.unit=p.unit}updateCostPreview()})}
window.removeIngredient=i=>{temp.ingredients.splice(i,1);renderIngredientRows();updateCostPreview()}
function renderBaseRows(){const el=$('baseRows');if(!el)return;el.innerHTML=temp.baseUses.map((i,ix)=>`<div class="lineRow"><div><label>Base</label><select data-base="baseId" data-i="${ix}">${baseOptions(i.baseId)}</select></div><div><label>Quantitat</label><input data-base="qty" data-i="${ix}" type="number" step="0.001" value="${n(i.qty)}"></div><div><label>Unitat</label><select data-base="unit" data-i="${ix}">${unitOptions(i.unit||'L')}</select></div><button class="btn bad small" onclick="removeBaseUse(${ix})">×</button></div>`).join('')||'<div class="muted" style="padding:10px">Sense bases.</div>';el.querySelectorAll('[data-base]').forEach(x=>x.oninput=e=>{const i=Number(e.target.dataset.i),k=e.target.dataset.base;temp.baseUses[i][k]=k==='qty'?n(e.target.value):e.target.value;if(k==='baseId'){const b=data.bases.find(x=>x.id===e.target.value);temp.baseUses[i].name=b?.name||'';if(b)temp.baseUses[i].unit=b.yieldUnit||'L'}updateCostPreview()})}
window.removeBaseUse=i=>{temp.baseUses.splice(i,1);renderBaseRows();updateCostPreview()}
function updateCostPreview(){const el=$('costPreview');if(!el)return;el.textContent=money(dishCost({ingredients:temp.ingredients,baseUses:temp.baseUses}))}
window.saveForm=async()=>{const {module,id}=editing,o=id?(data[module]||[]).find(x=>x.id===id):{id:uid(module.slice(0,4))};if(module==='suppliers')Object.assign(o,{name:$('f_name').value.trim(),tradeName:$('f_trade').value.trim(),taxId:$('f_tax').value.trim(),phone:$('f_phone').value.trim(),email:$('f_email').value.trim(),address:$('f_address').value.trim(),active:true});
 if(module==='products'){const fam=$('f_family').value;Object.assign(o,{code:$('f_code').value.trim()||nextCode(fam),name:$('f_name').value.trim(),family:fam,unit:$('f_unit').value,price:n($('f_price').value),stock:n($('f_stock').value),min:n($('f_min').value),supplierId:$('f_supplier').value,location:$('f_location').value.trim(),notes:$('f_notes').value.trim(),active:true});if(!o.name)return alert('Cal posar el nom del producte.')}
 if(module==='bases'){const exact=$('f_yield').value.trim(),minimum=$('f_yieldMin').value.trim(),maximum=$('f_yieldMax').value.trim();Object.assign(o,{name:$('f_name').value.trim(),type:$('f_type').value.trim(),station:$('f_station').value.trim(),initialQtyText:$('f_initial').value.trim(),yield:exact===''?null:n(exact),yieldMin:minimum===''?null:n(minimum),yieldMax:maximum===''?null:n(maximum),yieldPending:exact===''&&minimum===''&&maximum==='',yieldUnit:$('f_yieldUnit').value,packText:$('f_pack').value.trim(),life:$('f_life').value.trim(),conservation:$('f_conservation').value.trim(),ingredients:temp.ingredients,baseUses:temp.baseUses,process:$('f_process').value.trim(),techniques:o.techniques||[]});if(!o.name)return alert('Cal posar el nom de la base.')}
 if(module==='dishes'){Object.assign(o,{recipeStatus:'VALIDADA / REVISADA',name:$('f_name').value.trim(),cat:$('f_cat').value.trim(),station:$('f_station').value.trim(),sale:n($('f_sale').value),servings:n($('f_servings').value)||1,allergens:$('f_allergens').value.trim(),desc:$('f_desc').value.trim(),ingredients:temp.ingredients,baseUses:temp.baseUses,process:$('f_process').value.trim(),plating:$('f_plating').value.trim(),techniques:o.techniques||[],onMenu:$('f_onmenu').value==='true',zones:checkedZones()});if(!o.name)return alert('Cal posar el nom del plat.')}
 if(module==='saleItems'){Object.assign(o,{name:$('f_name').value.trim(),family:$('f_cat').value.trim(),price:n($('f_sale').value),onMenu:$('f_onmenu').value==='true',zones:checkedZones(),active:true,type:o.type||'beverage'});if(!o.name)return alert('Cal posar el nom de l’article.')}
 if(module==='documents')Object.assign(o,{designTemplate:$('f_design_template').value,accentColor:$('f_accent_color').value,type:$('f_type').value,title:$('f_title').value.trim(),subtitle:$('f_subtitle').value.trim(),client:$('f_client').value.trim(),date:$('f_date').value,price:$('f_price').value.trim(),items:[...document.querySelectorAll('.dishCheck:checked')].map(x=>x.value),notes:$('f_notes').value.trim(),footer:$('f_footer').value.trim(),publishReservations:$('f_type').value==='Menú'&&$('f_publish_res').value==='true',reservationPrice:n($('f_res_price').value),depositType:$('f_dep_type').value,depositValue:n($('f_dep_value').value),publicReservationNotes:$('f_public_notes').value.trim()});
 if(module==='employees'){Object.assign(o,{code:$('f_code').value.trim(),name:$('f_name').value.trim(),role:$('f_role').value.trim(),level:$('f_level').value,centreId:$('f_centre').value,companyId:contextValues().companyId,scope:'CENTRE',phone:$('f_phone').value.trim(),active:$('f_active').value==='Sí',tasks:$('f_tasks').value.trim(),responsibilities:$('f_responsibilities').value.trim(),notes:$('f_notes').value.trim()});if(!o.name)return alert('Cal posar el nom de l’empleat.');if(!o.centreId)return alert('Cal assignar un centre de treball.');if(!o.phone)return alert('Cal posar el telèfon de l’empleat per enviar-li l’activació.')}
 if(module==='schedules'){const eid=$('f_employee').value,e=data.employees.find(x=>x.id===eid);if(!e)return alert('Cal seleccionar un empleat.');if(!$('f_date').value)return alert('Cal indicar la data.');Object.assign(o,{employeeId:eid,employeeName:e.name,date:$('f_date').value,start:$('f_start').value,end:$('f_end').value,area:$('f_area').value.trim(),notes:$('f_notes').value.trim(),shiftTemplateId:editing.scheduleException?'':(o.shiftTemplateId||''),shiftCode:editing.scheduleException?'EXC':(o.shiftCode||''),exception:Boolean(editing.scheduleException)})}
 if(!id)(data[module]||[]).push(o);await save();closeModal();render()}
window.removeItem=async(module,id)=>{if(!confirm('Eliminar aquest registre?'))return;data[module]=(data[module]||[]).filter(x=>x.id!==id);await save();render()}

const ZONE_LABELS={sala:'Sala',terrassa:'Terrassa',jardi:'Jardí',grups:'Local vell / Grups'};
function zoneNames(z){return (z||[]).map(x=>ZONE_LABELS[x]||x)}
function zoneChecks(selected){const s=new Set(selected||[]);return Object.entries(ZONE_LABELS).map(([id,name])=>`<label class="zoneCheck"><input type="checkbox" class="zoneInput" value="${id}" ${s.has(id)?'checked':''}> ${esc(name)}</label>`).join('')}
function checkedZones(){return [...document.querySelectorAll('.zoneInput:checked')].map(x=>x.value)}
function itemPrice(item,zone){if(item.type==='beverage'&&item.sourcePrices){if(zone==='sala'&&item.sourcePrices.Sala!=null)return n(item.sourcePrices.Sala);if(zone==='terrassa'&&item.sourcePrices.Terraza!=null)return n(item.sourcePrices.Terraza)}return n(item.sale??item.price)}
function activeOrder(zone,tableId){return (data.tpvConfig?.orders||[]).find(o=>o.zone===zone&&o.tableId===tableId&&o.status!=='closed')}
function orderTotal(o){return (o?.lines||[]).reduce((s,l)=>s+n(l.qty)*n(l.price),0)}
function orderStatusLabel(o){return o.status==='bill'?'COMPTE':o.status==='sent'?'ENVIADA':'OBERTA'}
function cartaDishIds(){const ids=new Set();for(const doc of (data.documents||[])){if(norm(doc.type)==='carta'){for(const id of (doc.items||[]))ids.add(id)}}return ids}
function tpvItems(o){
 const zone=o.zone,carta=cartaDishIds();
 const dishes=(data.dishes||[]).filter(x=>(x.onMenu||carta.has(x.id))&&((x.zones||[]).includes(zone)||(!(x.zones||[]).length&&zone==='sala'))).map(x=>({id:x.id,name:x.name,family:x.cat||'PLATS',type:'dish',price:n(x.sale)}));
 const drinks=(data.saleItems||[]).filter(x=>x.active!==false&&x.onMenu&&(x.zones||[]).includes(zone)).map(x=>({...x,price:itemPrice(x,zone)}));
 return [...dishes,...drinks]
}
function tpvFamilies(items){
 const present=[...new Set(items.map(x=>x.family||'Altres'))];
 const preferred=data.tpvConfig?.familyOrder||[];
 return [...preferred.filter(x=>present.includes(x)),...present.filter(x=>!preferred.includes(x))]
}
function pageInfo(items,page,size){const pages=Math.max(1,Math.ceil(items.length/size));const p=Math.min(Math.max(0,page),pages-1);return {page:p,pages,start:p*size,items:items.slice(p*size,p*size+size)}}
function tpvProductPageSize(){return innerWidth<=720?8:innerWidth<=1000?12:15}
function tpvFamilyPageSize(){return innerWidth<=720?8:12}
function safeJs(s){return String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'")}

function renderTPV(){
 const cfg=data.tpvConfig||{zones:[],orders:[]},z=cfg.zones.find(x=>x.id===tpvZone)||cfg.zones[0];if(!z)return $('view').innerHTML='<div class="errBox">Falta configuració del TPV.</div>';
 const tabs=cfg.zones.map(x=>`<button class="zoneTab ${x.id===z.id?'active':''}" onclick="setTPVZone('${x.id}')">${esc(x.name)}</button>`).join('');
 let body='';
 if(z.id==='grups'){
   const groups=(data.reservations||[]).filter(r=>n(r.pax)>=11&&String(r.status||'').toLowerCase()!=='cancel·lada');
   body=`<div class="tableGrid">${groups.map(r=>`<button class="tableTile groupTile" onclick="openGroupOrder('${r.id}')"><strong>${esc(r.name||'Grup')}</strong><span>${esc(r.date||'')} ${esc(r.time||'')}</span><b>${esc(r.pax)} pax</b><small>${esc(r.menuTitle||'Menú especial')}</small></button>`).join('')||'<div class="panel">No hi ha reserves de grup actives.</div>'}</div>`;
 } else {
   body=`<div class="tableGrid">${(z.tables||[]).map(t=>{const o=activeOrder(z.id,t.id),st=o?orderStatusLabel(o):'LLIURE';return `<button class="tableTile ${o?'occupied':''} ${o?.status==='bill'?'bill':''}" onclick="openTableOrder('${z.id}','${t.id}')"><strong>${esc(t.name)}</strong><span>${t.min===t.max?`${t.max} pax`:`${t.min}–${t.max} pax`}</span><b>${st}</b>${o?`<small>${o.pax} pax · ${money(orderTotal(o))}</small>`:''}</button>`}).join('')}</div>`;
 }
 const open=(cfg.orders||[]).filter(o=>o.status!=='closed').length;
 $('view').innerHTML=`<div class="panel tpvHead"><div class="zoneTabs">${tabs}</div><div class="tpvCounter"><b>${open}</b><span>serveis oberts</span></div></div>${body}`;
}
window.setTPVZone=z=>{tpvZone=z;tpvCategory='';tpvProductPage=0;tpvFamilyPage=0;renderTPV()}
window.openTableOrder=async(zone,tableId)=>{const z=data.tpvConfig.zones.find(x=>x.id===zone),t=z?.tables.find(x=>x.id===tableId);if(!t)return;let o=activeOrder(zone,tableId);if(!o){const suggested=t.min||1;o={id:uid('ord'),zone,tableId,tableName:t.name,pax:suggested,status:'open',createdAt:new Date().toISOString(),lines:[]};data.tpvConfig.orders.push(o);await save()}tpvOrderId=o.id;tpvCategory='';tpvProductPage=0;tpvFamilyPage=0;renderOrderModal()}
window.openGroupOrder=async rid=>{const r=(data.reservations||[]).find(x=>x.id===rid);if(!r)return;let o=(data.tpvConfig.orders||[]).find(x=>x.zone==='grups'&&x.reservationId===rid&&x.status!=='closed');if(!o){o={id:uid('ord'),zone:'grups',tableId:'GRUP-'+rid,tableName:r.name||'Grup',reservationId:rid,pax:n(r.pax),status:'open',createdAt:new Date().toISOString(),lines:[],menuTitle:r.menuTitle||''};data.tpvConfig.orders.push(o);await save()}tpvOrderId=o.id;tpvCategory='';tpvProductPage=0;tpvFamilyPage=0;renderOrderModal()}

function renderOrderModal(){
 const o=(data.tpvConfig.orders||[]).find(x=>x.id===tpvOrderId);if(!o)return;
 const items=tpvItems(o),families=tpvFamilies(items);
 if(!families.includes(tpvCategory))tpvCategory=families[0]||'';
 const famPage=pageInfo(families,tpvFamilyPage,tpvFamilyPageSize());tpvFamilyPage=famPage.page;
 const visible=items.filter(x=>(x.family||'Altres')===tpvCategory);
 const prodPage=pageInfo(visible,tpvProductPage,tpvProductPageSize());tpvProductPage=prodPage.page;
 const lines=(o.lines||[]).map((l,i)=>`<div class="posTicketLine"><button class="posQtyMinus" onclick="changeOrderQty(${i},-1)">−</button><div><b>${esc(l.name)}</b><small>${l.qty} × ${money(l.price)}</small></div><strong>${money(n(l.price)*n(l.qty))}</strong><button class="posQtyPlus" onclick="changeOrderQty(${i},1)">+</button></div>`).join('')||'<div class="posEmpty">COMANDA BUIDA</div>';
 const familyButtons=famPage.items.map(c=>`<button class="posFamily ${c===tpvCategory?'active':''}" onclick="setTPVCategory('${safeJs(c)}')">${esc(c)}</button>`).join('');
 const productButtons=prodPage.items.map(x=>`<button class="posProduct" onclick="addOrderItem('${x.type}','${x.id}')"><b>${esc(x.name)}</b><span>${money(x.price)}</span></button>`).join('')||'<div class="posEmptyProducts">Sense articles en aquesta família.</div>';
 const famNav=famPage.pages>1?`<div class="posPager"><button onclick="setTPVFamilyPage(${famPage.page-1})" ${famPage.page===0?'disabled':''}>◀</button><b>${famPage.page+1}/${famPage.pages}</b><button onclick="setTPVFamilyPage(${famPage.page+1})" ${famPage.page===famPage.pages-1?'disabled':''}>▶</button></div>`:'';
 const prodNav=prodPage.pages>1?`<div class="posPager products"><button onclick="setTPVProductPage(${prodPage.page-1})" ${prodPage.page===0?'disabled':''}>◀ ANTERIOR</button><b>${prodPage.page+1}/${prodPage.pages}</b><button onclick="setTPVProductPage(${prodPage.page+1})" ${prodPage.page===prodPage.pages-1?'disabled':''}>SEGÜENT ▶</button></div>`:'';
 openModal(`${ZONE_LABELS[o.zone]||o.zone} · ${o.tableName}`,`<div class="posStandard"><div class="posTicket"><div class="posTicketHead"><div><strong>${esc(o.tableName)}</strong><span>${esc(ZONE_LABELS[o.zone]||o.zone)}</span></div><label>PAX <input id="tpv_pax" type="number" min="1" value="${esc(o.pax)}" onchange="saveOrderMeta()"></label><span class="posStatus ${o.status==='bill'?'bill':''}">${orderStatusLabel(o)}</span></div><div class="posTicketLines">${lines}</div><div class="posTicketTotal"><span>TOTAL</span><b>${money(orderTotal(o))}</b></div><div class="posTicketActions"><button class="posAction back" onclick="closeModal();tpvOrderId=null">← TAULES</button><button class="posAction send" onclick="orderStatus('sent')">ENVIAR CUINA</button><button class="posAction bill" onclick="orderStatus('bill')">COMPTE</button><button class="posAction close" onclick="closeOrder()">TANCAR TAULA</button></div></div><div class="posSelector"><div class="posFamilyArea"><div class="posFamilies">${familyButtons||'<div class="posEmptyProducts">Sense famílies.</div>'}</div>${famNav}</div><div class="posProducts">${productButtons}</div>${prodNav}</div></div>`);
 const modal=document.querySelector('.modal');if(modal)modal.classList.add('posModal');
}
window.setTPVCategory=c=>{tpvCategory=c;tpvProductPage=0;renderOrderModal()}
window.setTPVFamilyPage=p=>{tpvFamilyPage=Math.max(0,p);renderOrderModal()}
window.setTPVProductPage=p=>{tpvProductPage=Math.max(0,p);renderOrderModal()}
window.addOrderItem=async(type,id)=>{const o=(data.tpvConfig.orders||[]).find(x=>x.id===tpvOrderId);if(!o)return;let src=type==='dish'?(data.dishes||[]).find(x=>x.id===id):(data.saleItems||[]).find(x=>x.id===id);if(!src)return;const price=type==='dish'?n(src.sale):itemPrice(src,o.zone);const key=type+':'+id;let line=(o.lines||[]).find(x=>x.key===key);if(line)line.qty+=1;else o.lines.push({key,type,itemId:id,name:src.name,qty:1,price});o.updatedAt=new Date().toISOString();await save();renderOrderModal()}
window.changeOrderQty=async(i,delta)=>{const o=(data.tpvConfig.orders||[]).find(x=>x.id===tpvOrderId);if(!o||!o.lines[i])return;o.lines[i].qty+=delta;if(o.lines[i].qty<=0)o.lines.splice(i,1);o.updatedAt=new Date().toISOString();await save();renderOrderModal()}
window.saveOrderMeta=async()=>{const o=(data.tpvConfig.orders||[]).find(x=>x.id===tpvOrderId);if(!o)return;o.pax=Math.max(1,n($('tpv_pax').value)||1);o.updatedAt=new Date().toISOString();await save()}
window.orderStatus=async st=>{const o=(data.tpvConfig.orders||[]).find(x=>x.id===tpvOrderId);if(!o)return;o.pax=Math.max(1,n($('tpv_pax').value)||1);o.status=st;o.updatedAt=new Date().toISOString();await save();renderOrderModal()}
window.closeOrder=async()=>{const o=(data.tpvConfig.orders||[]).find(x=>x.id===tpvOrderId);if(!o)return;if(!confirm(`Tancar ${o.tableName} per ${money(orderTotal(o))}?`))return;o.status='closed';o.closedAt=new Date().toISOString();await save();closeModal();tpvOrderId=null;renderTPV()}

function renderSaleItems(){const arr=qfilter(data.saleItems||[]);const on=(data.saleItems||[]).filter(x=>x.onMenu).length;$('view').innerHTML=`<div class="panel"><div class="toolbar"><button class="btn" onclick="openForm('saleItems')">Nou / Crear</button><span class="badge ok">${on} publicats al TPV</span><input id="search" class="search" placeholder="Buscar beguda, família..." oninput="render()"></div></div><div class="panel"><div class="notice"><b>Import Ágora:</b> conservem els formats i els preus d'origen. Aquí pots corregir nom/preu, activar o desactivar i decidir zones. No duplica les Fitxes de plats.</div><div class="tableWrap"><table><thead><tr><th>Article / format</th><th>Família</th><th>Preu base</th><th>Ágora Sala</th><th>Ágora Terrassa</th><th>A la carta</th><th>Zones</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td><b>${esc(x.name)}</b>${x.productName&&x.productName!==x.name?`<br><span class="muted">${esc(x.productName)}</span>`:''}</td><td>${esc(x.family||'')}</td><td>${money(x.price)}</td><td>${x.sourcePrices?.Sala==null?'—':money(x.sourcePrices.Sala)}</td><td>${x.sourcePrices?.Terraza==null?'—':money(x.sourcePrices.Terraza)}</td><td>${x.onMenu?'<span class="badge ok">Sí</span>':'No'}</td><td>${esc(zoneNames(x.zones).join(', ')||'—')}</td><td>${actions('saleItems',x.id)}</td></tr>`).join('')||'<tr><td colspan="8">Sense articles de venda.</td></tr>'}</tbody></table></div></div>`}

function printHeader(title){const c=data.company||{};return `<div style="display:flex;gap:12px;align-items:center;border-bottom:2px solid #222;padding-bottom:8px;margin-bottom:10px">${c.logo?`<img src="${c.logo}" style="max-width:75px;max-height:60px">`:''}<div><h2 style="margin:0">${esc(c.name||'Casa Mestres')}</h2><div>${esc(c.legal||'')} ${esc(c.tax||'')}</div><small>${esc(c.address||'')}</small></div><div style="margin-left:auto;text-align:right"><b>${esc(title)}</b><br>${new Date().toLocaleDateString('ca-ES')}</div></div>`}
window.printList=module=>{let rows='',heads='';if(module==='products'){heads='<th>Codi</th><th>Producte</th><th>Família</th><th>Unitat</th><th>Preu</th><th>Stock</th>';rows=data.products.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.name)}</td><td>${esc(x.family)}</td><td>${esc(x.unit)}</td><td>${money(x.price)}</td><td>${esc(x.stock)}</td></tr>`).join('')}else if(module==='suppliers'){heads='<th>Proveïdor</th><th>CIF</th><th>Telèfon</th><th>Email</th>';rows=data.suppliers.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.taxId||'')}</td><td>${esc(x.phone||'')}</td><td>${esc(x.email||'')}</td></tr>`).join('')}else if(module==='bases'){heads='<th>Base</th><th>Rendiment</th><th>Cost</th>';rows=data.bases.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(baseYieldText(x))}</td><td>${money(baseCost(x))}</td></tr>`).join('')}else if(module==='dishes'){heads='<th>Plat</th><th>Venda</th><th>Cost</th><th>%</th>';rows=data.dishes.map(x=>{const c=dishCost(x);return `<tr><td>${esc(x.name)}</td><td>${money(x.sale)}</td><td>${money(c)}</td><td>${n(x.sale)?(c/n(x.sale)*100).toFixed(1):'0'}%</td></tr>`}).join('')}else if(module==='documents'){heads='<th>Tipus</th><th>Títol</th><th>Client</th><th>Preu</th>';rows=data.documents.map(x=>`<tr><td>${esc(x.type)}</td><td>${esc(x.title)}</td><td>${esc(x.client||'')}</td><td>${esc(x.price||'')}</td></tr>`).join('')}else if(module==='employees'){heads='<th>Codi</th><th>Nom</th><th>Funció</th><th>Telèfon</th>';rows=data.employees.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.name)}</td><td>${esc(x.role||x.roleBase||'')}</td><td>${esc(x.phone||'')}</td></tr>`).join('')}else if(module==='schedules'){heads='<th>Data</th><th>Empleat</th><th>Entrada</th><th>Sortida</th><th>Àrea</th>';rows=data.schedules.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.employeeName)}</td><td>${esc(x.start)}</td><td>${esc(x.end)}</td><td>${esc(x.area||'')}</td></tr>`).join('')}else if(module==='reservations'){heads='<th>Data</th><th>Client</th><th>Pax</th><th>Menú</th><th>Fiança</th><th>Estat</th>';rows=(data.reservations||[]).map(x=>`<tr><td>${esc(x.date)} ${esc(x.time)}</td><td>${esc(x.name)} · ${esc(x.phone)}</td><td>${esc(x.pax)}</td><td>${esc(x.menuTitle||'')}</td><td>${money(x.depositAmount)}</td><td>${esc(x.status||'')}</td></tr>`).join('')}else if(module==='punches'){heads='<th>Data</th><th>Empleat</th><th>Acció</th><th>GPS</th>';rows=data.punches.map(x=>`<tr><td>${new Date(x.dateTime).toLocaleString('ca-ES')}</td><td>${esc(x.employeeName)}</td><td>${esc(x.type)}</td><td>${esc(x.status)}</td></tr>`).join('')}printHTML(`<div class="draftDoc">${printHeader(titles[module]?.[0]||module)}<table><thead><tr>${heads}</tr></thead><tbody>${rows}</tbody></table></div>`)}
window.printSingle=(module,id,mode='draft')=>{const o=(data[module]||[]).find(x=>x.id===id);if(!o)return;if(module==='bases'){const items=[...(o.ingredients||[]).map(i=>{const p=data.products.find(x=>x.id===i.productId);return `<tr><td>${esc(p?.name||i.name)}</td><td>${esc(ingredientQtyText(i))}</td><td>Producte</td></tr>`}),...(o.baseUses||[]).map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.qty)} ${esc(i.unit)}</td><td>Base</td></tr>`)].join('');printHTML(`<div class="draftDoc">${printHeader('Fitxa tècnica de base')}<h1>${esc(o.name)}</h1><table><tr><th>Quantitat inicial</th><td>${esc(o.initialQtyText||(o.initialQty!=null?`${o.initialQty} ${o.initialUnit||''}`:'—'))}</td><th>Rendiment</th><td>${esc(baseYieldText(o))}</td></tr><tr><th>Envasat</th><td>${esc(o.packText||'—')}</td><th>Conservació</th><td>${esc(o.conservation||'—')}</td></tr></table><h3>Ingredients i bases</h3><table><tr><th>Producte / base</th><th>Quantitat</th><th>Tipus</th></tr>${items}</table><h3>Elaboració</h3><p>${esc(o.process||'Pendent de documentar').replace(/\n/g,'<br>')}</p>${o.transcriptionNotes?`<p><b>Pendent de revisió:</b> ${esc(o.transcriptionNotes)}</p>`:''}</div>`)}else if(module==='dishes'){const items=[...(o.ingredients||[]).map(i=>{const p=data.products.find(x=>x.id===i.productId);return `<tr><td>${esc(p?.name||i.name)}</td><td>${esc(i.qty)}</td><td>${esc(i.unit)}</td><td>${money(ingredientCost(i))}</td></tr>`}),...(o.baseUses||[]).map(i=>`<tr><td>Base: ${esc(i.name)}</td><td>${esc(i.qty)}</td><td>${esc(i.unit)}</td><td>—</td></tr>`)].join('');printHTML(`<div class="draftDoc">${printHeader('Fitxa tècnica de plat')}<h1>${esc(o.name)}</h1><table><tr><th>Categoria</th><td>${esc(o.cat)}</td><th>Venda</th><td>${money(o.sale)}</td></tr><tr><th>Racions</th><td>${esc(o.servings)}</td><th>Cost / escandall</th><td>${money(dishCost(o))}</td></tr><tr><th>Al·lèrgens</th><td colspan="3">${esc(o.allergens)}</td></tr></table><h3>Ingredients</h3><table><tr><th>Producte / base</th><th>Quantitat</th><th>Unitat</th><th>Cost</th></tr>${items}</table><h3>Elaboració</h3><p>${esc(o.process).replace(/\n/g,'<br>')}</p><h3>Acabat i emplatat</h3><p>${esc(o.plating)}</p></div>`)}else if(module==='documents'){const names=(o.items||[]).map(id=>data.dishes.find(d=>d.id===id)?.name||id);if(mode==='premium')printHTML(`<div class="premiumDoc ${esc(o.designTemplate||'elegant')}" style="--doc-accent:${esc(o.accentColor||'#9b7a3d')}">${data.company.logo?`<img src="${data.company.logo}" style="max-height:85px">`:''}<div class="title">${esc(o.title)}</div><h3>${esc(o.subtitle||'')}</h3>${names.map(x=>`<div class="dish">${esc(x)}</div>`).join('')}<h2>${esc(o.price||'')}</h2><p>${esc(o.notes||'').replace(/\n/g,'<br>')}</p><p><i>${esc(o.footer||'')}</i></p></div>`);else printHTML(`<div class="draftDoc">${printHeader(o.type)}<h1>${esc(o.title)}</h1><p><b>Client:</b> ${esc(o.client||'')} &nbsp; <b>Data:</b> ${esc(o.date||'')}</p><table><tr><th>Plats / contingut</th></tr>${names.map(x=>`<tr><td>${esc(x)}</td></tr>`).join('')}</table><p>${esc(o.notes||'').replace(/\n/g,'<br>')}</p><h2>${esc(o.price||'')}</h2></div>`)}}
function printHTML(html){$('printArea').innerHTML=html;window.print()}
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(titles[h]){active=h;render()}});const h=location.hash.slice(1);if(titles[h])active=h;load().catch(e=>{$('view').innerHTML=`<div class="errBox">${esc(e.message)}</div>`});
})();
